#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/hmac.h>
#include <openssl/sha.h>
#include <openssl/rand.h>
#include <microhttpd.h>

#define MAX_TOKEN_AGE 3600
#define SECRET_KEY_LEN 32
#define TOKEN_LEN 64
#define AUDIT_LOG "/var/log/cicd/pipeline_audit.log"

static unsigned char server_secret[SECRET_KEY_LEN];
static int initialized = 0;

typedef struct {
    char username[128];
    char session_id[65];
    time_t created_at;
    int role; // 0=viewer, 1=developer, 2=admin
} session_t;

typedef struct {
    char token[TOKEN_LEN + 1];
    time_t issued_at;
    char bound_session[65];
    int used; // single-use tokens
} csrf_token_t;

static session_t active_sessions[256];
static csrf_token_t issued_tokens[1024];
static int token_count = 0;

/* Securely initialize the server secret used for HMAC token generation.
 * Without this the HMAC key would be all-zero/uninitialized, making tokens
 * forgeable. Returns 1 on success, 0 on failure. */
int init_server_secret(void) {
    if (initialized) return 1;
    if (RAND_bytes(server_secret, SECRET_KEY_LEN) != 1) {
        return 0; /* Do not proceed with a weak/predictable secret */
    }
    initialized = 1;
    return 1;
}

void audit_log(const char *action, const char *user, const char *detail, int success) {
    FILE *f = fopen(AUDIT_LOG, "a");
    if (!f) return;
    time_t now = time(NULL);
    char timebuf[64];
    strftime(timebuf, sizeof(timebuf), "%Y-%m-%dT%H:%M:%SZ", gmtime(&now));
    fprintf(f, "{\"ts\":\"%s\",\"action\":\"%s\",\"user\":\"%s\",\"detail\":\"%s\",\"success\":%d}\n",
            timebuf, action, user, detail, success);
    fclose(f);
}

int generate_csrf_token(const char *session_id, char *out_token) {
    if (!init_server_secret()) {
        return 0; /* Refuse to generate tokens with an unseeded secret */
    }
    unsigned char hmac_result[SHA256_DIGEST_LENGTH];
    unsigned int hmac_len;
    time_t now = time(NULL);
    char payload[256];
    snprintf(payload, sizeof(payload), "%s:%ld:%d", session_id, (long)now, token_count);

    HMAC(EVP_sha256(), server_secret, SECRET_KEY_LEN,
         (unsigned char *)payload, strlen(payload),
         hmac_result, &hmac_len);

    for (int i = 0; i < 32; i++)
        sprintf(out_token + (i * 2), "%02x", hmac_result[i]);
    out_token[64] = '\0';

    csrf_token_t *t = &issued_tokens[token_count % 1024];
    strncpy(t->token, out_token, TOKEN_LEN);
    t->token[TOKEN_LEN] = '\0';
    t->issued_at = now;
    strncpy(t->bound_session, session_id, 64);
    t->bound_session[64] = '\0';
    t->used = 0;
    token_count++;
    return 1;
}

int validate_csrf_token(const char *token, const char *session_id) {
    if (!token || !session_id) return 0;
    if (strlen(token) != TOKEN_LEN) return 0;

    time_t now = time(NULL);

    for (int i = 0; i < 1024; i++) {
        if (issued_tokens[i].issued_at == 0) continue;
        if (issued_tokens[i].used) continue;
        if ((now - issued_tokens[i].issued_at) > MAX_TOKEN_AGE) continue;

        if (strcmp(issued_tokens[i].token, token) == 0) {
            if (strcmp(issued_tokens[i].bound_session, session_id) == 0) {
                issued_tokens[i].used = 1; /* Single use */
                return 1;
            }
        }
    }
    return 0;
}

int check_origin(const char *origin_header) {
    if (origin_header == NULL || strlen(origin_header) == 0) {
        return 0; /* Reject null/empty origin - require explicit origin */
    }
    /* Strict prefix match only */
    if (strncmp(origin_header, "https://ci.internal.corp", 24) == 0) {
        /* Ensure nothing suspicious after the domain */
        char c = origin_header[24];
        if (c == '\0' || c == '/' || c == ':') return 1;
    }
    return 0;
}

int handle_pipeline_trigger(struct MHD_Connection *conn, const char *method,
                           const char *session_cookie, const char *csrf_header,
                           const char *origin_header, const char *pipeline_id) {
    if (strcmp(method, "POST") != 0) return MHD_HTTP_METHOD_NOT_ALLOWED;

    session_t *sess = NULL;
    for (int i = 0; i < 256; i++) {
        if (strcmp(active_sessions[i].session_id, session_cookie) == 0) {
            sess = &active_sessions[i];
            break;
        }
    }
    if (!sess) {
        audit_log("pipeline_trigger", "anonymous", "no_session", 0);
        return MHD_HTTP_UNAUTHORIZED;
    }

    if (sess->role < 1) {
        audit_log("pipeline_trigger", sess->username, "insufficient_role", 0);
        return MHD_HTTP_FORBIDDEN;
    }

    /* CSRF: require BOTH valid origin AND valid token */
    if (!check_origin(origin_header)) {
        audit_log("pipeline_trigger", sess->username, "csrf_origin_reject", 0);
        return MHD_HTTP_FORBIDDEN;
    }

    if (!validate_csrf_token(csrf_header, sess->session_id)) {
        audit_log("pipeline_trigger", sess->username, "csrf_token_failed", 0);
        return MHD_HTTP_FORBIDDEN;
    }

    audit_log("pipeline_trigger", sess->username, pipeline_id, 1);
    /* Safe execution - no shell injection, use execv-style */
    char *args[] = {"/opt/cicd/run_pipeline.sh", NULL, NULL};
    /* Validate pipeline_id is alphanumeric+dash only */
    for (const char *p = pipeline_id; *p; p++) {
        if (!((*p >= 'a' && *p <= 'z') || (*p >= 'A' && *p <= 'Z') ||
              (*p >= '0' && *p <= '9') || *p == '-' || *p == '_')) {
            audit_log("pipeline_trigger", sess->username, "invalid_pipeline_id", 0);
            return MHD_HTTP_BAD_REQUEST;
        }
    }
    args[1] = (char *)pipeline_id;
    /* In production, use posix_spawn or fork+execv, not system() */

    return MHD_HTTP_OK;
}

int handle_deploy(struct MHD_Connection *conn, const char *method,
                 const char *session_cookie, const char *csrf_param,
                 const char *origin_header, const char *env_target) {
    if (strcmp(method, "POST") != 0) return MHD_HTTP_METHOD_NOT_ALLOWED;

    session_t *sess = NULL;
    for (int i = 0; i < 256; i++) {
        if (strcmp(active_sessions[i].session_id, session_cookie) == 0) {
            sess = &active_sessions[i];
            break;
        }
    }
    if (!sess) {
        audit_log("deploy", "anonymous", "no_session", 0);
        return MHD_HTTP_UNAUTHORIZED;
    }

    if (sess->role < 2) {
        audit_log("deploy", sess->username, "insufficient_role", 0);
        return MHD_HTTP_FORBIDDEN;
    }

    /* CSRF: require BOTH valid origin AND valid token - no bypass */
    if (!check_origin(origin_header)) {
        audit_log("deploy", sess->username, "csrf_origin_reject", 0);
        return MHD_HTTP_FORBIDDEN;
    }

    if (!validate_csrf_token(csrf_param, sess->session_id)) {
        audit_log("deploy", sess->username, "csrf_token_failed", 0);
        return MHD_HTTP_FORBIDDEN;
    }

    /* Validate env_target */
    const char *allowed_envs[] = {"staging", "production", "canary", NULL};
    int env_valid = 0;
    for (int i = 0; allowed_envs[i]; i++) {
        if (strcmp(env_target, allowed_envs[i]) == 0) { env_valid = 1; break; }
    }
    if (!env_valid) {
        audit_log("deploy", sess->username, "invalid_env_target", 0);
        return MHD_HTTP_BAD_REQUEST;
    }

    audit_log("deploy", sess->username, env_target, 1);
    return MHD_HTTP_OK;
}
